import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, positionLocal, sin, length, vec2, float, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Shape, ExtrudeGeometry, DirectionalLight, Color } = ctx.THREE;

  const root = new Group();
  const disposables = [];
  const timelines = [];
  const killTween = (t) => { if (t) t.kill(); };

  const spec = config.intent?.visualSpec ?? {};
  const colors = spec.colors ?? {};
  const cAccent = colors.accent ?? '#ff2a38';
  const cPaper = colors.paper ?? '#e8ecf2';
  const cInactive = '#a6adba';
  const stops = colors.gradientStops ?? [{ at: 0, hex: '#1b1b23' }, { at: 1, hex: '#101015' }];

  // ---------------------------------------------------------------
  // STAGE BACKDROP — vertical gradient plane, never a flat void
  // ---------------------------------------------------------------
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = mix(color(stops[1].hex), color(stops[0].hex), uv().y);
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---------------------------------------------------------------
  // NODE-LOCAL RIM LIGHT (accent hue, behind-left, intensity <= 1.5)
  // ---------------------------------------------------------------
  const rim = new DirectionalLight(new Color(cAccent), 0.85);
  rim.position.set(-2.5, 1.2, -1.5);
  rim.target.position.set(0, 0, 0);
  root.add(rim);
  root.add(rim.target);

  // ---------------------------------------------------------------
  // CONTACT SHADOW PLANE (radial falloff, 35% opacity, offset 0.06 down)
  // ---------------------------------------------------------------
  const shadowGeo = new PlaneGeometry(4.6, 1.1);
  const shadowMat = new MeshBasicNodeMaterial();
  shadowMat.transparent = true;
  shadowMat.depthWrite = false;
  shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
  const dist = length(uv().sub(vec2(0.5, 0.5)).mul(vec2(2.0, 2.0)));
  shadowMat.opacityNode = float(1.0).sub(dist).clamp(0.0, 1.0).pow(1.6).mul(0.35);
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.position.set(0, -0.06, 0.0);
  root.add(shadow);
  disposables.push(shadowGeo, shadowMat);

  // ---------------------------------------------------------------
  // DOCK GROUP (floats z +0.15, rise-in on mount)
  // ---------------------------------------------------------------
  const dock = new Group();
  dock.position.set(0, -0.4, 0.15);
  root.add(dock);

  // Machined rail — rounded rect, chamfered edge, brushed-metal PBR
  const railW = 3.6, railH = 0.5, r = 0.1;
  const shape = new Shape();
  const hw = railW / 2, hh = railH / 2;
  shape.moveTo(-hw + r, -hh);
  shape.lineTo(hw - r, -hh);
  shape.quadraticCurveTo(hw, -hh, hw, -hh + r);
  shape.lineTo(hw, hh - r);
  shape.quadraticCurveTo(hw, hh, hw - r, hh);
  shape.lineTo(-hw + r, hh);
  shape.quadraticCurveTo(-hw, hh, -hw, hh - r);
  shape.lineTo(-hw, -hh + r);
  shape.quadraticCurveTo(-hw, -hh, -hw + r, -hh);

  const railGeo = new ExtrudeGeometry(shape, {
    depth: 0.06,
    bevelEnabled: true,
    bevelThickness: 0.02,
    bevelSize: 0.02,
    bevelSegments: 3,
    curveSegments: 12,
  });
  railGeo.translate(0, 0, -0.03);

  const railMat = new MeshPhysicalNodeMaterial();
  const railT = positionLocal.y.add(hh).div(railH).clamp(0.0, 1.0);
  const brushed = sin(positionLocal.x.mul(420.0)).mul(0.012);
  railMat.colorNode = mix(color(stops[1].hex), color(stops[0].hex), railT).add(vec3(brushed, brushed, brushed));
  railMat.roughness = 0.55;
  railMat.metalness = 0.5;
  railMat.clearcoat = 0.2;
  railMat.clearcoatRoughness = 0.35;
  railMat.anisotropy = 0.6;
  const rail = new Mesh(railGeo, railMat);
  dock.add(rail);
  disposables.push(railGeo, railMat);

  // ---------------------------------------------------------------
  // NAV ENTRIES
  // ---------------------------------------------------------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const fallback = [
    { text: 'HOME', role: 'nav-active' },
    { text: 'FEATURES', role: 'nav-item' },
    { text: 'COLLECTION', role: 'nav-item' },
    { text: 'PRICING', role: 'nav-item' },
    { text: 'JOURNAL', role: 'nav-item' },
  ];
  const navItems = items.length ? items : fallback;

  const routeMap = {
    HOME: 'hub-home',
    FEATURES: 'hub-features',
    COLLECTION: 'hub-collection',
    PRICING: 'hub-pricing',
    JOURNAL: 'hub-journal',
  };

  const spacing = 0.68;
  const startX = -spacing * (navItems.length - 1) / 2;
  const TEXT_SCALE = 0.0075;
  const entries = [];
  let activeIndex = navItems.findIndex((it) => it.role === 'nav-active');
  if (activeIndex < 0) activeIndex = 0;

  const hitGeo = new PlaneGeometry(0.6, 0.34);
  const hitMat = new MeshBasicNodeMaterial();
  hitMat.transparent = true;
  hitMat.opacity = 0;
  hitMat.depthWrite = false;
  disposables.push(hitGeo, hitMat);

  for (let i = 0; i < navItems.length; i++) {
    const item = navItems[i];
    const text = String(item.text ?? '');
    const isActive = i === activeIndex;
    const cell = new Group();
    cell.position.set(startX + i * spacing, 0, 0.07);
    dock.add(cell);

    const fontSize = item.typography?.fontSize ?? 13;
    const label = ctx.fontAtlas.createText(text, {
      fontSize,
      color: isActive ? cPaper : cInactive,
      align: 'center',
      letterSpacingPx: fontSize * 0.08,
    });
    label.scale.setScalar(TEXT_SCALE);
    label.position.set(0, 0, 0.06);
    cell.add(label);

    const textMats = [];
    label.traverse((o) => { if (o.material && o.material.color) textMats.push(o.material); });

    const hit = new Mesh(hitGeo, hitMat);
    hit.position.set(0, 0, 0.08);
    hit.userData.navIndex = i;
    cell.add(hit);

    entries.push({ index: i, text, cell, label, textMats, hit, hoverTween: null, pressTween: null });
  }

  // Active underline bar — signal red emissive, seated 0.06 below baseline
  const barGeo = new PlaneGeometry(0.28, 0.025);
  const barMat = new MeshBasicNodeMaterial();
  const accCol = new Color(cAccent);
  barMat.colorNode = vec3(accCol.r * 1.8, accCol.g * 1.8, accCol.b * 1.8);
  const underline = new Mesh(barGeo, barMat);
  underline.position.set(startX + activeIndex * spacing, -0.11, 0.14);
  dock.add(underline);
  disposables.push(barGeo, barMat);

  // ---------------------------------------------------------------
  // MOUNT MOTION — rise-in y -> 0, power3.out 0.7s, then one slow idle
  // ---------------------------------------------------------------
  const mountTl = gsap.timeline();
  mountTl.to(dock.position, { y: 0, duration: 0.7, ease: 'power3.out' });
  timelines.push(mountTl);

  const idleTl = gsap.timeline({ repeat: -1, yoyo: true, delay: 0.8 });
  idleTl.to(dock.position, { y: 0.02, duration: 3.2, ease: 'sine.inOut' });
  timelines.push(idleTl);

  // ---------------------------------------------------------------
  // INTERACTION
  // ---------------------------------------------------------------
  const findEntry = (hit) => {
    let obj = hit?.object ?? hit;
    while (obj) {
      if (obj.userData && obj.userData.navIndex !== undefined) return entries[obj.userData.navIndex];
      obj = obj.parent;
    }
    return null;
  };

  const tintEntry = (entry, hex, dur) => {
    const target = new Color(hex);
    for (const m of entry.textMats) {
      killTween(entry.hoverTween);
      entry.hoverTween = gsap.to(m.color, { r: target.r, g: target.g, b: target.b, duration: dur, ease: 'power2.out' });
    }
  };

  const setActive = (idx) => {
    if (idx === activeIndex || !entries[idx]) return;
    const prev = entries[activeIndex];
    const next = entries[idx];
    activeIndex = idx;
    tintEntry(prev, cInactive, 0.16);
    tintEntry(next, cPaper, 0.16);
    const barTl = gsap.timeline();
    barTl.to(underline.position, {
      x: startX + idx * spacing,
      duration: 0.26,
      ease: 'back.out(1.4)',
    });
    barTl.fromTo(underline.scale, { x: 1.04 }, { x: 1.0, duration: 0.4, ease: 'power4.out' }, 0.1);
    timelines.push(barTl);
  };

  root.userData.handlers = {
    onHoverStart: (hit) => {
      const entry = findEntry(hit);
      if (!entry || entry.index === activeIndex) return;
      tintEntry(entry, cPaper, 0.16);
    },
    onHoverEnd: (hit) => {
      const entry = findEntry(hit);
      if (!entry || entry.index === activeIndex) return;
      tintEntry(entry, cInactive, 0.16);
    },
    onPointerDown: (hit) => {
      const entry = findEntry(hit);
      if (!entry) return;
      killTween(entry.pressTween);
      entry.pressTween = gsap.to(entry.cell, {
        duration: 0.12,
        ease: 'back.out(1.7)',
        onUpdate: null,
      });
      gsap.to(entry.cell.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(1.7)' });
      gsap.to(entry.cell.position, { z: 0.04, duration: 0.12, ease: 'back.out(1.7)' });
    },
    onPointerUp: (hit) => {
      const entry = findEntry(hit);
      if (!entry) return;
      gsap.to(entry.cell.scale, { x: 1, y: 1, z: 1, duration: 0.2, ease: 'power2.out' });
      gsap.to(entry.cell.position, { z: 0.07, duration: 0.2, ease: 'power2.out' });
    },
    onClick: (hit) => {
      const entry = findEntry(hit);
      if (!entry) return;
      setActive(entry.index);
      const route = routeMap[entry.text.toUpperCase()] ?? 'hub-home';
      ctx.emit('navigate', { to: route });
    },
  };

  // ---------------------------------------------------------------
  // CLEANUP
  // ---------------------------------------------------------------
  root.userData.cleanup = () => {
    for (const tl of timelines) tl.kill();
    for (const e of entries) {
      killTween(e.hoverTween);
      killTween(e.pressTween);
      gsap.killTweensOf(e.cell.scale);
      gsap.killTweensOf(e.cell.position);
      for (const m of e.textMats) gsap.killTweensOf(m.color);
    }
    gsap.killTweensOf(dock.position);
    gsap.killTweensOf(underline.position);
    gsap.killTweensOf(underline.scale);
    for (const d of disposables) { if (d.dispose) d.dispose(); }
    rim.dispose?.();
  };

  return root;
}
